class Livro {
  String titulo;
  int paginas;

    Livro(String titulo) {
      this(titulo, 100);
    }

    Livro(String titulo, int paginas) {
      this.titulo = titulo;
      this.paginas = paginas;
    }

    void alterar(String titulo, int paginas) {
      this.titulo = titulo;
      this.paginas += paginas;
    }

    public static void main(String[] args) {
      Livro a = new Livro("Java");
      Livro b = new Livro(a.titulo, a.paginas + 50);

         a.alterar("POO", 20);
         b.alterar(a.titulo, a.paginas);

         System.out.println(a.titulo + " " + a.paginas + " | "
             + b.titulo + " " + b.paginas);
    }
}

